/// The C ABI's stream: a context and the I/O callback (`value` the field or local the operation reads or writes).
struct EeScenarioStream {
  void *ctx;
  int32_t (*io)(void *ctx, uint32_t op, uint32_t slot, unsigned long index, void *value);
};

/// One store on a computer player: `field` the position of the field in its kind's list (`EE_SM_AI_LONGS`,
/// `EE_SM_AI_FLOATS`, `EE_SM_AI_BUILDINGS`, `EE_SM_AI_CALLS` in ee/EESMAIFields.h: the modules below in order).
struct EeScenarioAiWrite {
  uint32_t kind;
  uint32_t field;
  long long_value;
  float float_value;
};

/// `EESMTrigger`'s numbers, in the class's order (its condition and effect entries stay the C++'s).
struct EeScenarioTriggerFields {
  unsigned long mConditionDuration;
  unsigned long mConditionStartTime;
  unsigned long mID;
  bool mIsOn;
  bool mHasFired;
  bool mIsLooping;
  bool mIsInCinematic;
};

/// `EESMArea`'s saved values (a copy the C++ fills from its members and stores back): the anchor tile, the
/// rectangle, the flags, the select mode, the tiles' time and the id.
struct EeScenarioAreaSave {
  long anchor_x;
  long anchor_y;
  float left;
  float top;
  float right;
  float bottom;
  bool has_rectangle;
  bool has_anchor;
  unsigned long select_mode;
  unsigned long tiles_time;
  unsigned long id;
};

/// One timed effect (`EESMTimedEffect`): an `mEffects` index, the scenario time it is due, the cinematic flag, and
/// whether it has run (the round erases those).
struct EeScenarioTimedEntry {
  unsigned long mEffectIndex;
  unsigned long mTime;
  bool mIsInCinematic;
  bool mHasRun;
};

/// `EEScenarioManager`'s numbers, in the class's order.
struct EeScenarioManagerFields {
  long mGameResult;
  /// The camera zoom `StartCinematic` saves.
  float mSavedZoom;
  float mStartX;
  float mStartY;
  /// The scenario clock (ms).
  float mTime;
  /// The time since the last trigger round (ms).
  float mTriggerTimer;
  float mCinematicStartTime;
  long mSavedCameraMode;
  unsigned long mNextTriggerID;
  unsigned long mNextConditionID;
  unsigned long mNextEffectID;
  unsigned long mNextObjectID;
  unsigned long mNextAreaID;
  /// Set by `Reset`: new pending effects are not recorded until `ApplyPendingEffects` has run.
  bool mB234;
  bool mIsMovingCamera;
  bool mShowDebugIDs;
  bool mIsShowingDialog;
  bool mIsEndingCinematic;
};

/// The C ABI's round host: the manager's numbers and queue, and the operation callback.
struct EeScenarioRoundHost {
  void *ctx;
  EeScenarioManagerFields *fields;
  EeScenarioTimedQueue *queue;
  int64_t (*op)(void *ctx, uint32_t op, int64_t a, int64_t b, float time);
};

/// The new value: `value` for the int kinds and the flag, `fvalue` for the float kinds.
struct EeScenarioClassValue {
  long value;
  float fvalue;
};

/// The C++ host of the lists (`EESMListOp` in EEScenarioManager.cpp): the manager's numbers and timed effects, and
/// one operation callback (`EE_SCENARIO_LIST_OP_*`; `text` a NUL-terminated name for `SET_NAME` and `OUT_NAME`).
struct EeScenarioListHost {
  void *ctx;
  EeScenarioManagerFields *manager;
  EeScenarioTimedQueue *timed;
  void *(*op)(void *ctx, uint32_t op, uint32_t list, size_t index, void *element, const char *text);
};

/// The C++ host of the text file (`EESMTextOp` in EEScenarioManager.cpp): the lists' host and one operation
/// callback (`EE_SCENARIO_TEXT_OP_*`: `slot` a text slot or an error kind, `value` a player, an id or the file's
/// version, `text` and `text2` NUL-terminated strings).
struct EeScenarioTextHost {
  const EeScenarioListHost *lists;
  void *ctx;
  void *(*op)(void *ctx,
              uint32_t op,
              uint32_t slot,
              long value,
              void *element,
              const char *text,
              const char *text2);
};

/// One trigger entry: the NOT flag (0/1) or the delay, the operator, the condition or effect index.
struct EeScenarioEntry {
  unsigned long first;
  long op;
  unsigned long value;
};

